'use strict';

// MAIN //

var invalid = [];
var test;

test = {
	'code': [
		'/**',
		'* Squares a number.',
		'*',
		'* @param {number} x    - input number',
		'* @returns {number} x squared',
		'*/',
		'function square( x ) {',
		'  return x*x;',
		'}'
	].join( '\n' ),
	'errors': [
		{
			'message': 'hyphen should be preceded by only one space'
		}
	]
};
invalid.push( test );

